import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"Stage 3 · Computer Operator","description":"Hearth Stage 3 development module: device agentd, GUI observation, human takeover, low-risk desktop actions, high-risk approvals, and desktop security boundaries.","frontmatter":{"title":"Stage 3 · Computer Operator","description":"Hearth Stage 3 development module: device agentd, GUI observation, human takeover, low-risk desktop actions, high-risk approvals, and desktop security boundaries.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-3.md","filePath":"en/delivery/stage-3.md","lastUpdated":1793761874000}'),i={name:"en/delivery/stage-3.md"};function s(n,e,l,d,c,p){return a(),o("div",null,[...e[0]||(e[0]=[r('<p class="eyebrow">MODULE 3 / 7</p><h1 id="stage-3-·-computer-operator" tabindex="-1">Stage 3 · Computer Operator <a class="header-anchor" href="#stage-3-·-computer-operator" aria-label="Permalink to &quot;Stage 3 · Computer Operator&quot;">​</a></h1><p class="lead">Cover desktop software without APIs and cross-application workflows. Observe first, add takeover second, allow low-risk actions third, and only then open high-risk actions. Automation is blocked when outcomes cannot be verified or controlled.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>Recovery, approval, idempotency, receipts, and browser isolation from Stages 1–2 are stable.</li><li>Device capabilities, window scopes, application allowlists, and irreversible-action lists are defined.</li><li>Takeover and revocation paths exist before automation.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Register desktop devices.</strong> Implement pairing, <code>agentd</code> registration, capability catalog, health checks, permission declarations, device details, disconnect, and revocation.</li><li><strong>Build observation and takeover.</strong> Connect the accessibility tree, screenshots, window scopes, live takeover, mouse/keyboard pause and handback, screenshot redaction, and audit events.</li><li><strong>Complete low-risk GUI actions.</strong> Within allowlisted applications, open files, navigate menus, fill drafts, and export results, then verify with screenshots or the accessibility tree.</li><li><strong>Handle partial completion and failure.</strong> Detect partial success, lost windows, input contention, permission changes, and unrecoverable states; offer pause, takeover, or rollback.</li><li><strong>Open high-risk actions.</strong> Add isolated virtual desktops, impact preview, explicit confirmation, irreversible-action lists, snapshots, compensation scripts, and recovery drills.</li><li><strong>Complete the Stage 3 release.</strong> Evaluate at least 5 real desktop tasks for completion, takeover experience, security boundaries, Tokens, and manual minutes.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><p>Each increment now has four layers: outcome and gate → four work packages → engineering map and interfaces → acceptance rehearsal. Packages can be split across developers, but merge in dependency order; completing one package does not complete the increment.</p><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td><a href="/hearth-os/en/delivery/stage-3/d3-1.html">D3.1</a> Device agentd and visibility</td><td>Users see trusted devices, capabilities, and online state</td><td>Pairing, capability catalog, health check, revocation</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/d3-2.html">D3.2</a> GUI observation and takeover</td><td>Users can view, pause, operate, and hand back</td><td>Takeover UI, window scope, state record, screenshot redaction</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/d3-3.html">D3.3</a> Low-risk GUI actions and verification</td><td>Allowlisted low-risk actions show evidence</td><td>App allowlist, action preview, result verification, retry</td></tr><tr><td><a href="/hearth-os/en/delivery/stage-3/d3-4.html">D3.4</a> High-risk GUI and Stage 3 release</td><td>High-risk actions show impact, confirmation, and compensation</td><td>Isolated desktop, approval, snapshot, recovery, 5 real tasks</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] At least 5 real desktop tasks can be completed and verified.</li><li>[ ] Users can pause, operate, hand back, or terminate a takeover.</li><li>[ ] GUI failures do not leave half-completed high-risk states.</li><li>[ ] Password vaults are not read and security settings are not changed beyond scope.</li><li>[ ] Tokens and manual minutes are acceptable; users understand undo or compensation.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Automating desktop actions without verification or takeover.</li><li>Unbounded system-level control.</li><li>Treating OCR or screenshot recognition as the sole source of truth.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-4.html">Stage 4 · Proactive Personal Agent</a> and add bounded proactivity on top of recovery and approval.</p>',16)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
